mapper.delete:
delete from biz_stock_flow
 where create_time < #{cutoff}
   and flow_id in (select flow_id from biz_stock_flow_archive)
 order by flow_id
 limit #{limit}

mapper.insert:
insert into biz_point_log_archive
    (log_id, member_id, change_type, points_change, points_after, batch_id,
     ref_no, create_by, create_time, remark, archived_at)
select p.log_id, p.member_id, p.change_type, p.points_change, p.points_after, p.batch_id,
       p.ref_no, p.create_by, p.create_time, p.remark, #{archivedAt}
  from biz_point_log p
 where p.create_time < #{cutoff}
   and not exists (select 1 from biz_point_log_archive a where a.log_id = p.log_id)
 order by p.log_id
 limit #{limit}

mapper.delete:
delete from biz_point_log
 where create_time < #{cutoff}
   and log_id in (select log_id from biz_point_log_archive)
 order by log_id
 limit #{limit}

delete from biz_ai_call_log
 where create_time < #{cutoff}
   and log_id in (select log_id from biz_ai_call_log_archive)
 order by log_id
 limit #{limit}
